import React from 'react';
import { Workflow } from '../../../models/Help';
import styles from './EscalationRules.module.css';

interface EscalationRulesProps {
  slaEscalation: NonNullable<Workflow['slaEscalation']>;
  note?: string;
}

export const EscalationRules: React.FC<EscalationRulesProps> = ({ slaEscalation, note }) => {
  return (
    <div className={styles.wrapper}>
      <div className={styles.tableWrapper}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Priority</th>
              <th>Response Time</th>
              <th>Resolve Time</th>
              <th>Action khi vi phạm SLA</th>
            </tr>
          </thead>
          <tbody>
            {slaEscalation.map((row, i) => (
              <tr key={i} className={styles.row}>
                <td>
                  <span className={styles.priorityBadge} style={{ background: row.priorityStyle.background, color: row.priorityStyle.color }}>
                    {row.priority}
                  </span>
                </td>
                <td>{row.responseTime}</td>
                <td>{row.resolveTime}</td>
                <td>
                  {row.actions.map((action, j) => (
                    <div key={j} className={styles.actionItem}>• {action}</div>
                  ))}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {note && <p className={styles.note}>{note}</p>}
    </div>
  );
};
