import React from 'react';
import { Workflow } from '../../../models/Help';
import styles from './RolesMatrix.module.css';

interface RolesMatrixProps {
  matrix: NonNullable<Workflow['rolesMatrix']>;
}

const roleClass: Record<string, string> = {
  user: styles.roleUser,
  staff: styles.roleStaff,
  lead: styles.roleLead,
  manager: styles.roleManager,
  system: styles.roleSystem,
};

export const RolesMatrix: React.FC<RolesMatrixProps> = ({ matrix }) => {
  return (
    <div>
      <div className={styles.tableWrapper}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Vai trò</th>
              {matrix.columns.map((col, i) => (
                <th key={i}>{col}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {matrix.rows.map((row, i) => (
              <tr key={i} className={styles.row}>
                <td>
                  <span className={`${styles.roleBadge} ${roleClass[row.roleClass] ?? ''}`}>
                    {row.role}
                  </span>
                </td>
                {matrix.columns.map((col, j) => (
                  <td key={j} className={styles.cell}>
                    {row.columns[col] ?? '—'}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className={styles.legend}>
        <span className={styles.legendItem}><span className={styles.ok}>✅</span> Có quyền</span>
        <span className={styles.legendItem}><span className={styles.no}>❌</span> Không có quyền</span>
        <span className={styles.legendItem}><span className={styles.partial}>⚠️</span> Có điều kiện</span>
      </div>
    </div>
  );
};
