/**
 * HistoryFilters Component
 * Filter controls for history items — responsive (mobile toggle + desktop row)
 */

import React, { useState } from 'react';
import { HistoryItemType } from '../../../models/History';
import { TicketPriority } from '../../../models/Ticket';
import { TaskPriority } from '../../../models/Task';
import { Select, SelectOption } from '../../common';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './HistoryFilters.module.css';

interface HistoryFiltersProps {
  search: string;
  onSearchChange: (value: string) => void;
  dateRange: string;
  onDateRangeChange: (value: string) => void;
  itemType: HistoryItemType | '';
  onItemTypeChange: (value: HistoryItemType | '') => void;
  priority: TicketPriority | TaskPriority | '';
  onPriorityChange: (value: TicketPriority | TaskPriority | '') => void;
}

const DATE_OPTIONS: SelectOption[] = [
  { value: 'all',     label: 'Tất cả thời gian' },
  { value: 'today',   label: 'Hôm nay' },
  { value: 'week',    label: 'Tuần này' },
  { value: 'month',   label: 'Tháng này' },
  { value: 'quarter', label: 'Quý này' },
  { value: 'year',    label: 'Năm nay' },
];

const TYPE_OPTIONS: SelectOption[] = [
  { value: '',                    label: 'Tất cả loại' },
  { value: HistoryItemType.Ticket, label: 'Phiếu yêu cầu' },
  { value: HistoryItemType.Task,   label: 'Công việc' },
];

const PRIORITY_OPTIONS: SelectOption[] = [
  { value: '',         label: 'Tất cả ưu tiên' },
  { value: 'critical', label: 'Khẩn cấp' },
  { value: 'high',     label: 'Cao' },
  { value: 'medium',   label: 'Trung bình' },
  { value: 'low',      label: 'Thấp' },
];

export const HistoryFilters: React.FC<HistoryFiltersProps> = ({
  search,
  onSearchChange,
  dateRange,
  onDateRangeChange,
  itemType,
  onItemTypeChange,
  priority,
  onPriorityChange,
}) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);

  const activeFilterCount =
    (dateRange !== 'all' && dateRange !== 'month' ? 1 : 0) +
    (itemType !== '' ? 1 : 0) +
    (priority !== '' ? 1 : 0);

  const hasActiveFilters = activeFilterCount > 0;

  const handleClear = () => {
    onDateRangeChange('all');
    onItemTypeChange('');
    onPriorityChange('');
    setIsExpanded(false);
  };

  // ─── Mobile ───────────────────────────────────────────────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && (
          <div className={styles.backdrop} onClick={() => setIsExpanded(false)} />
        )}
        <div className={styles.container}>
          <div className={styles.mobileRow}>
            <div className={styles.searchBox}>
              <i className="fas fa-search" />
              <input
                type="text"
                placeholder="Tìm kiếm..."
                value={search}
                onChange={(e) => onSearchChange(e.target.value)}
              />
            </div>
            <button
              className={styles.filterToggle}
              onClick={() => setIsExpanded((v) => !v)}
              type="button"
              aria-expanded={isExpanded}
            >
              <i className="fas fa-filter" />
              {activeFilterCount > 0 && (
                <span className={styles.filterBadge}>{activeFilterCount}</span>
              )}
              <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
            </button>
          </div>
          {isExpanded && (
            <div className={styles.mobileFilters}>
              <Select
                value={dateRange}
                onChange={(e) => onDateRangeChange(e.target.value)}
                options={DATE_OPTIONS}
                fullWidth
              />
              <Select
                value={itemType}
                onChange={(e) => onItemTypeChange(e.target.value as HistoryItemType | '')}
                options={TYPE_OPTIONS}
                fullWidth
              />
              <Select
                value={priority}
                onChange={(e) =>
                  onPriorityChange(e.target.value as TicketPriority | TaskPriority | '')
                }
                options={PRIORITY_OPTIONS}
                fullWidth
              />
              {hasActiveFilters && (
                <button className={styles.clearButton} onClick={handleClear} type="button">
                  <i className="fas fa-times-circle" /> Xóa bộ lọc
                </button>
              )}
            </div>
          )}
        </div>
      </>
    );
  }

  // ─── Desktop ──────────────────────────────────────────────────────────────
  return (
    <div className={styles.container}>
      <div className={styles.desktopRow}>
        <div className={styles.searchBox}>
          <i className="fas fa-search" />
          <input
            type="text"
            placeholder="Tìm kiếm theo tên, mã công việc..."
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
        </div>
        <Select
          value={dateRange}
          onChange={(e) => onDateRangeChange(e.target.value)}
          options={DATE_OPTIONS}
          size="small"
        />
        <Select
          value={itemType}
          onChange={(e) => onItemTypeChange(e.target.value as HistoryItemType | '')}
          options={TYPE_OPTIONS}
          size="small"
        />
        <Select
          value={priority}
          onChange={(e) =>
            onPriorityChange(e.target.value as TicketPriority | TaskPriority | '')
          }
          options={PRIORITY_OPTIONS}
          size="small"
        />
        {hasActiveFilters && (
          <button className={styles.clearButton} onClick={handleClear} type="button">
            <i className="fas fa-times-circle" /> Xóa
          </button>
        )}
      </div>
    </div>
  );
};
