/**
 * useSignalREvent — React hook that subscribes to a SignalR hub event
 * and automatically unsubscribes on unmount.
 *
 * Uses a ref-based stable callback wrapper so the caller's handler can
 * close over the latest component state without triggering re-subscriptions.
 *
 * Example:
 *   useSignalREvent('NewMessage', (payload) => {
 *     setMessages(prev => [...prev, payload.message]);
 *   });
 */

import { useEffect, useRef } from 'react';
import { signalRService } from './service';
import { HubEventName, HubEventPayloadMap } from './types';

export function useSignalREvent<E extends HubEventName>(
  event: E,
  handler: (payload: HubEventPayloadMap[E]) => void,
): void {
  // Always keep the latest handler in a ref so the stable wrapper
  // below never goes stale, even if the caller re-creates the function.
  const handlerRef = useRef(handler);
  handlerRef.current = handler;

  useEffect(() => {
    // Stable wrapper that delegates to the latest handlerRef
    const stableHandler = (payload: HubEventPayloadMap[E]) => {
      handlerRef.current(payload);
    };

    signalRService.on(event, stableHandler);
    return () => {
      signalRService.off(event, stableHandler);
    };
    // Only re-subscribe when the event name itself changes (extremely rare).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [event]);
}
