import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import {
  MedicalIncident,
  MedicalIncidentFilters,
  MedicalIncidentStats,
  IncidentStatus,
} from '../../models/MedicalIncident';
import { medicalIncidentService } from '../../services/medicalIncidents';

// ─────────────────────────────────────────────────────────────────────────────
// State
// ─────────────────────────────────────────────────────────────────────────────

interface MedicalIncidentsState {
  items: MedicalIncident[];
  selectedIncident: MedicalIncident | null;
  filters: MedicalIncidentFilters;
  loading: boolean;
  saving: boolean;
  error: string | null;
  stats: MedicalIncidentStats;
  pagination: {
    page: number;
    pageSize: number;
    totalCount: number;
  };
}

const initialState: MedicalIncidentsState = {
  items: [],
  selectedIncident: null,
  filters: {},
  loading: false,
  saving: false,
  error: null,
  stats: {
    total: 0,
    draft: 0,
    submitted: 0,
    inAnalysis: 0,
    resolved: 0,
    closed: 0,
    severeCount: 0,
  },
  pagination: {
    page: 1,
    pageSize: 20,
    totalCount: 0,
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// Thunks
// ─────────────────────────────────────────────────────────────────────────────

export const fetchMedicalIncidents = createAsyncThunk(
  'medicalIncidents/fetchList',
  async (_, thunkAPI) => {
    const state = thunkAPI.getState() as { medicalIncidents: MedicalIncidentsState };
    const { filters, pagination } = state.medicalIncidents;
    return medicalIncidentService.getList(filters, pagination.page, pagination.pageSize);
  },
);

export const fetchMedicalIncidentStats = createAsyncThunk(
  'medicalIncidents/fetchStats',
  async () => medicalIncidentService.getStats(),
);

export const fetchMedicalIncidentById = createAsyncThunk(
  'medicalIncidents/fetchById',
  async (id: string) => medicalIncidentService.getById(id),
);

export const createMedicalIncident = createAsyncThunk(
  'medicalIncidents/create',
  async (data: Partial<MedicalIncident>) => medicalIncidentService.create(data),
);

export const updateMedicalIncident = createAsyncThunk(
  'medicalIncidents/update',
  async ({ id, data }: { id: string; data: Partial<MedicalIncident> }) =>
    medicalIncidentService.update(id, data),
);

export const deleteMedicalIncident = createAsyncThunk(
  'medicalIncidents/delete',
  async (id: string) => {
    await medicalIncidentService.delete(id);
    return id;
  },
);

export const startIncidentAnalysis = createAsyncThunk(
  'medicalIncidents/startAnalysis',
  async (id: string) => medicalIncidentService.startAnalysis(id),
);

export const submitIncidentAnalysis = createAsyncThunk(
  'medicalIncidents/submitAnalysis',
  async (id: string) => medicalIncidentService.submitAnalysis(id),
);

export const submitIncidentFeedback = createAsyncThunk(
  'medicalIncidents/submitFeedback',
  async ({ id, rating, feedback }: { id: string; rating: number; feedback: string }) =>
    medicalIncidentService.submitFeedback(id, rating, feedback),
);

export const toggleIncidentServiceMismatch = createAsyncThunk(
  'medicalIncidents/toggleServiceMismatch',
  async ({ id, isServiceMismatch }: { id: string; isServiceMismatch: boolean }) =>
    medicalIncidentService.toggleServiceMismatch(id, isServiceMismatch),
);

// ─────────────────────────────────────────────────────────────────────────────
// Slice
// ─────────────────────────────────────────────────────────────────────────────

const medicalIncidentsSlice = createSlice({
  name: 'medicalIncidents',
  initialState,
  reducers: {
    setFilters(state, action: PayloadAction<MedicalIncidentFilters>) {
      state.filters = action.payload;
      state.pagination.page = 1;
    },
    setPage(state, action: PayloadAction<number>) {
      state.pagination.page = action.payload;
    },
    setSelectedIncident(state, action: PayloadAction<MedicalIncident | null>) {
      state.selectedIncident = action.payload;
    },
    clearError(state) {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    // fetchList
    builder
      .addCase(fetchMedicalIncidents.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchMedicalIncidents.fulfilled, (state, action) => {
        state.loading = false;
        state.items = action.payload.items;
        state.pagination.totalCount = action.payload.total;
        state.pagination.page = action.payload.page;
      })
      .addCase(fetchMedicalIncidents.rejected, (state, action) => {
        if (action.meta.aborted) return;
        state.loading = false;
        state.error = action.error.message ?? 'Lỗi tải danh sách sự cố';
      });

    // fetchStats
    builder
      .addCase(fetchMedicalIncidentStats.fulfilled, (state, action) => {
        state.stats = action.payload;
      });

    // fetchById
    builder
      .addCase(fetchMedicalIncidentById.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchMedicalIncidentById.fulfilled, (state, action) => {
        state.loading = false;
        state.selectedIncident = action.payload;
      })
      .addCase(fetchMedicalIncidentById.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message ?? 'Lỗi tải sự cố';
      });

    // create
    builder
      .addCase(createMedicalIncident.pending, (state) => {
        state.saving = true;
        state.error = null;
      })
      .addCase(createMedicalIncident.fulfilled, (state, action) => {
        state.saving = false;
        state.items = [action.payload, ...state.items];
        state.pagination.totalCount += 1;
        state.stats.total += 1;
        state.stats.draft += 1;
      })
      .addCase(createMedicalIncident.rejected, (state, action) => {
        state.saving = false;
        state.error = action.error.message ?? 'Lỗi tạo sự cố';
      });

    // update
    builder
      .addCase(updateMedicalIncident.pending, (state) => {
        state.saving = true;
        state.error = null;
      })
      .addCase(updateMedicalIncident.fulfilled, (state, action) => {
        state.saving = false;
        state.items = state.items.map((i) =>
          i.id === action.payload.id ? action.payload : i,
        );
        if (state.selectedIncident?.id === action.payload.id) {
          state.selectedIncident = action.payload;
        }
      })
      .addCase(updateMedicalIncident.rejected, (state, action) => {
        state.saving = false;
        state.error = action.error.message ?? 'Lỗi cập nhật sự cố';
      });

    // delete
    builder
      .addCase(deleteMedicalIncident.fulfilled, (state, action) => {
        const removed = state.items.find((i) => i.id === action.payload);
        state.items = state.items.filter((i) => i.id !== action.payload);
        state.pagination.totalCount = Math.max(0, state.pagination.totalCount - 1);
        if (removed) {
          state.stats.total = Math.max(0, state.stats.total - 1);
          if (removed.status === IncidentStatus.Draft)
            state.stats.draft = Math.max(0, state.stats.draft - 1);
        }
      });

    // action thunks: update selectedIncident on success
    const updateSelected = (state: typeof initialState, updated: MedicalIncident) => {
      const idx = state.items.findIndex((i) => i.id === updated.id);
      if (idx >= 0) state.items[idx] = updated;
      if (state.selectedIncident?.id === updated.id) state.selectedIncident = updated;
    };

    builder
      .addCase(startIncidentAnalysis.pending, (state) => { state.saving = true; state.error = null; })
      .addCase(startIncidentAnalysis.fulfilled, (state, action) => {
        state.saving = false;
        updateSelected(state, action.payload);
      })
      .addCase(startIncidentAnalysis.rejected, (state, action) => {
        state.saving = false;
        state.error = action.error.message ?? 'Lỗi bắt đầu phân tích';
      });

    builder
      .addCase(submitIncidentAnalysis.pending, (state) => { state.saving = true; state.error = null; })
      .addCase(submitIncidentAnalysis.fulfilled, (state, action) => {
        state.saving = false;
        updateSelected(state, action.payload);
      })
      .addCase(submitIncidentAnalysis.rejected, (state, action) => {
        state.saving = false;
        state.error = action.error.message ?? 'Lỗi hoàn thành phân tích';
      });

    builder
      .addCase(submitIncidentFeedback.pending, (state) => { state.saving = true; state.error = null; })
      .addCase(submitIncidentFeedback.fulfilled, (state, action) => {
        state.saving = false;
        updateSelected(state, action.payload);
      })
      .addCase(submitIncidentFeedback.rejected, (state, action) => {
        state.saving = false;
        state.error = action.error.message ?? 'Lỗi gửi đánh giá';
      });

    builder
      .addCase(toggleIncidentServiceMismatch.pending, (state) => { state.saving = true; state.error = null; })
      .addCase(toggleIncidentServiceMismatch.fulfilled, (state, action) => {
        state.saving = false;
        updateSelected(state, action.payload);
      })
      .addCase(toggleIncidentServiceMismatch.rejected, (state, action) => {
        state.saving = false;
        state.error = action.error.message ?? 'Lỗi cập nhật trạng thái nhầm dịch vụ';
      });
  },
});

export const { setFilters, setPage, setSelectedIncident, clearError } =
  medicalIncidentsSlice.actions;

export default medicalIncidentsSlice.reducer;
