import React from 'react';
import { Task } from '../../../../models/Task';
import styles from './RelatedTasksCard.module.css';

interface RelatedTasksCardProps {
  relatedTasks?: Task[];
}

export const RelatedTasksCard: React.FC<RelatedTasksCardProps> = ({ relatedTasks }) => {
  const hasRelatedTasks = relatedTasks && relatedTasks.length > 0;

  return (
    <div className={styles.relatedTasksCard}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>Tasks Liên Quan</h3>
        {hasRelatedTasks && (
          <span className={styles.count}>{relatedTasks.length}</span>
        )}
      </div>
      <div className={styles.cardBody}>
        {!hasRelatedTasks ? (
          <div className={styles.emptyState}>
            <i className="fas fa-link"></i>
            <p>Chưa có task liên quan</p>
          </div>
        ) : (
          <div className={styles.tasksList}>
            {relatedTasks.map((task) => (
              <div key={task.id} className={styles.taskItem}>
                <span className={styles.idCode}>{task.idCode || task.id}</span>
                <span className={styles.taskTitle}>{task.title}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};
