import React, {
  useState,
  useEffect,
  useRef,
  useCallback,
} from 'react';
import { userService } from '../../../services/user';
import { User } from '../../../models/User';
import styles from './UserSearchInput.module.css';

export interface UserSearchInputProps {
  /** The currently selected user's ID */
  value?: string;
  /** Code to display in the lookup input (staffId or username) */
  staffId?: string;
  /** Full name to display in the readonly name input */
  fullName?: string;
  /** Called when a user is selected: (userId, staffId, fullName) */
  onChange: (userId: string, staffId: string, fullName: string) => void;
  /** Show department filter dropdown. Defaults to true. */
  showDepartmentFilter?: boolean;
  /** Pre-selected department ID (filters results) */
  departmentId?: string;
  /** Label shown above the inputs */
  label?: string;
  /** Placeholder for the code/lookup input */
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  /** Inline error message */
  error?: string;
  /**
   * Whether to show the separate name input beside the lookup input.
   * - `true` (default): lookup input shows staffId, name input shows fullName.
   * - `false`: only the lookup input is rendered (full width).
   *   When a user is selected, the lookup input displays fullName instead of staffId.
   */
  showNameInput?: boolean;
}

const PAGE_SIZE = 20;

export const UserSearchInput: React.FC<UserSearchInputProps> = ({
  value,
  staffId,
  fullName,
  onChange,
  showDepartmentFilter = true,
  departmentId: propDepartmentId,
  label = 'Người thực hiện',
  placeholder = 'Nhập mã hoặc tên...',
  required = false,
  disabled = false,
  error,
  showNameInput = true,
}) => {
  const [term, setTerm] = useState('');
  const [deptId, setDeptId] = useState(propDepartmentId ?? '');
  const [departments, setDepartments] = useState<{ id: string; name: string }[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const sentinelRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ── Load departments for filter dropdown ────────────────────────────────────
  useEffect(() => {
    if (!showDepartmentFilter) return;
    userService
      .getUsers({ pageSize: 200 })
      .then((res) => {
        const deptMap = new Map<string, string>();
        res.items.forEach((u) => {
          if (u.departmentId && u.departmentName) {
            deptMap.set(u.departmentId, u.departmentName);
          }
        });
        setDepartments(
          Array.from(deptMap.entries()).map(([id, name]) => ({ id, name }))
        );
      })
      .catch(() => {});
  }, [showDepartmentFilter]);

  // ── Fetch users (page 1 / reset) ────────────────────────────────────────────
  const fetchUsers = useCallback(
    async (searchTerm: string, departmentId: string, resetPage: boolean) => {
      setLoading(true);
      const nextPage = resetPage ? 1 : page + 1;
      try {
        const res = await userService.getUsers({
          search: searchTerm || undefined,
          departmentId: departmentId || undefined,
          page: nextPage,
          pageSize: PAGE_SIZE,
        });
        setUsers((prev) => (resetPage ? res.items : [...prev, ...res.items]));
        setPage(res.page);
        setTotalPages(res.totalPages);
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    },
    [page]
  );

  // Debounced search when term or dept changes
  useEffect(() => {
    if (!isOpen) return;
    if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
    searchTimerRef.current = setTimeout(() => {
      fetchUsers(term, deptId, true);
    }, 300);
    return () => {
      if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [term, deptId, isOpen]);

  // ── IntersectionObserver for infinite scroll ────────────────────────────────
  useEffect(() => {
    if (!sentinelRef.current) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting && !loading && page < totalPages) {
          fetchUsers(term, deptId, false);
        }
      },
      { root: dropdownRef.current, threshold: 0.1 }
    );
    observer.observe(sentinelRef.current);
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading, page, totalPages, isOpen]);

  // ── Close dropdown on outside click ─────────────────────────────────────────
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  // ── Handlers ────────────────────────────────────────────────────────────────
  const handleTermChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTerm(e.target.value);
    setIsOpen(true);
  };

  const handleFocus = () => {
    setIsOpen(true);
  };

  const handleSelect = (user: User) => {
    onChange(user.id, user.staffId ?? user.username, user.fullName);
    //console.log('Selected user:', user);
    //setValue
    setTerm('');
    setIsOpen(false);
  };

  const handleDeptChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setDeptId(e.target.value);
  };

  const handleClear = () => {
    onChange('', '', '');
    setTerm('');
  };

  const hasSelection = !!value;

  // ── Render ──────────────────────────────────────────────────────────────────
  return (
    <div
      className={`${styles.container} ${error ? styles.hasError : ''} ${disabled ? styles.disabled : ''}`}
      ref={containerRef}
    >
      {label && (
        <label className={styles.label}>
          {label}
          {required && <span className={styles.required}> *</span>}
        </label>
      )}

      {/* Department filter */}
      {showDepartmentFilter && (
        <div className={styles.deptFilter}>
          <select
            className={styles.deptSelect}
            value={deptId}
            onChange={handleDeptChange}
            disabled={disabled}
          >
            <option value="">Tất cả phòng ban</option>
            {departments.map((d) => (
              <option key={d.id} value={d.id}>
                {d.name}
              </option>
            ))}
          </select>
        </div>
      )}

      {/* Input row: code lookup + optional readonly name */}
      <div className={styles.inputRow}>
        <div className={`${styles.lookupWrapper} ${!showNameInput ? styles.lookupWrapperFull : ''}`}>
          <input
            type="text"
            className={styles.lookupInput}
            value={hasSelection ? (showNameInput ? (staffId ?? '') : (fullName ?? '')) : term}
            onChange={handleTermChange}
            onFocus={handleFocus}
            placeholder={placeholder}
            disabled={disabled}
            readOnly={hasSelection}
            required={required}
            autoComplete="off"
          />
          {hasSelection && !disabled && (
            <button
              type="button"
              className={styles.clearBtn}
              onClick={handleClear}
              title="Xoá lựa chọn"
            >
              ✕
            </button>
          )}
          {!hasSelection && (
            <span className={styles.searchIcon}>
              <i className="fas fa-search" />
            </span>
          )}
        </div>

        {showNameInput && (
          <input
            type="text"
            className={styles.nameInput}
            value={fullName ?? ''}
            readOnly
            placeholder="Họ và tên"
            tabIndex={-1}
          />
        )}
      </div>

      {/* Dropdown */}
      {isOpen && !disabled && (
        <div className={styles.dropdown} ref={dropdownRef}>
          {loading && users.length === 0 ? (
            <div className={styles.loadingRow}>
              <i className="fas fa-spinner fa-spin" /> Đang tải...
            </div>
          ) : users.length === 0 ? (
            <div className={styles.emptyRow}>Không tìm thấy kết quả</div>
          ) : (
            <>
              <div className={styles.userGrid}>
                {users.map((u) => (
                  <button
                    key={u.id}
                    type="button"
                    className={`${styles.userCard} ${value === u.id ? styles.selected : ''}`}
                    onClick={() => handleSelect(u)}
                  >
                    {/* StaffId badge (leading) */}
                    {u.staffId && (
                      <span className={styles.staffBadge}>{u.staffId}</span>
                    )}
                    {/* Name */}
                    <span className={styles.cardName}>{u.fullName}</span>
                    {/* Meta: phone · dept (right, inline) */}
                    <span className={styles.cardMeta}>
                      {u.phone && (
                        <span className={styles.metaPhone}>
                          <i className="fas fa-phone" /> {u.phone}
                        </span>
                      )}
                      {u.departmentName && (
                        <span className={styles.metaDept}>
                          <i className="fas fa-building" /> {u.departmentName}
                        </span>
                      )}
                    </span>
                  </button>
                ))}
              </div>

              {/* Load-more sentinel */}
              {page < totalPages && (
                <div ref={sentinelRef} className={styles.sentinel}>
                  {loading && (
                    <span className={styles.loadMoreHint}>
                      <i className="fas fa-spinner fa-spin" /> Đang tải thêm...
                    </span>
                  )}
                </div>
              )}
            </>
          )}
        </div>
      )}

      {error && <span className={styles.errorMsg}>{error}</span>}
    </div>
  );
};
